draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // brain
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.lineWidth = 3;
  ctx.stroke();

  // thought bubble
  ctx.beginPath();
  ctx.arc(W/2 + 70 * Math.sin(t), H/2 - 70 * Math.cos(t), 30, 0, 2 * Math.PI);
  ctx.lineWidth = 3;
  ctx.stroke();

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2, H - 50, 10, 0, 2 * Math.PI); // head
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H - 40);
  ctx.lineTo(W/2, H - 20); // body
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 30);
  ctx.lineTo(W/2 - 20, H - 50); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 30);
  ctx.lineTo(W/2 + 20, H - 50); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 20);
  ctx.lineTo(W/2 - 10, H); // leg
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 20);
  ctx.lineTo(W/2 + 10, H); // leg
  ctx.stroke();

  ctx.restore();
}
